33	/**
34	 * Mostly used as a facade for all Petclinic controllers
35	 * Also a placeholder for @Transactional and @Cacheable annotations
36	 *
37	 * @author Michael Isvy
38	 * @author Vitaliy Fedoriv
39	 */
40	@Service
41	public class ClinicServiceImpl implements ClinicService {
42	
43	    private final PetRepository petRepository;
44	    private final VetRepository vetRepository;
45	    private final OwnerRepository ownerRepository;
46	    private final VisitRepository visitRepository;
47	    private final SpecialtyRepository specialtyRepository;
48	    private final PetTypeRepository petTypeRepository;
49	
50	    public ClinicServiceImpl(
51	        PetRepository petRepository,
52	        VetRepository vetRepository,
53	        OwnerRepository ownerRepository,
54	        VisitRepository visitRepository,
55	        SpecialtyRepository specialtyRepository,
56	        PetTypeRepository petTypeRepository) {
57	        this.petRepository = petRepository;
58	        this.vetRepository = vetRepository;
59	        this.ownerRepository = ownerRepository;
60	        this.visitRepository = visitRepository;
61	        this.specialtyRepository = specialtyRepository;
62	        this.petTypeRepository = petTypeRepository;
63	    }
64	
65	    @Override
66	    @Transactional(readOnly = true)
67	    public Collection<Pet> findAllPets() throws DataAccessException {
68	        return petRepository.findAll();
69	    }
70	
71	    @Override
72	    @Transactional(readOnly = true)
73	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
74	        return petRepository.findAll(pageable);
75	    }
76	
77	    @Override
78	    @Transactional
79	    public void deletePet(Pet pet) throws DataAccessException {
80	        petRepository.delete(pet);
81	    }
82	
83	    @Override
84	    @Transactional(readOnly = true)
85	    public Visit findVisitById(int visitId) throws DataAccessException {
86	        return findEntityById(() -> visitRepository.findById(visitId));
87	    }
88	
89	    @Override
90	    @Transactional(readOnly = true)
91	    public Collection<Visit> findAllVisits() throws DataAccessException {
92	        return visitRepository.findAll();
93	    }
94	
95	    @Override
96	    @Transactional
97	    public void deleteVisit(Visit visit) throws DataAccessException {
98	        visitRepository.delete(visit);
99	    }
100	
101	    @Override
102	    @Transactional(readOnly = true)
103	    public Vet findVetById(int id) throws DataAccessException {
104	        return findEntityById(() -> vetRepository.findById(id));
105	    }
106	
107	    @Override
108	    @Transactional(readOnly = true)
109	    public Collection<Vet> findAllVets() throws DataAccessException {
110	        return vetRepository.findAll();
111	    }
112	
113	    @Override
114	    @Transactional
115	    public void saveVet(Vet vet) throws DataAccessException {
116	        vetRepository.save(vet);
117	    }
118	
119	    @Override
120	    @Transactional
121	    public void deleteVet(Vet vet) throws DataAccessException {
122	        vetRepository.delete(vet);
123	    }
124	
125	    @Override
126	    @Transactional(readOnly = true)
127	    public Collection<Owner> findAllOwners() throws DataAccessException {
128	        return ownerRepository.findAll();
129	    }
130	
131	    @Override
