133	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
134	        if (lastName != null) {
135	            return ownerRepository.findByLastName(lastName, pageable);
136	        }
137	        return ownerRepository.findAll(pageable);
138	    }
